// pt-br message catalog, typed `Partial<Record<MessageId, string>>`:
// an id it lacks renders the English until it is translated (backfilled in
// batches; docs/frontend/i18n/README.md), and an id en no longer has is a
// compile error.
//
// Terms and style: docs/frontend/i18n/es-pt-br.md. Brazilian Portuguese,
// addressing the reader as você; sentence case; product nouns are Portuguese
// (agente, computador, servidor) and brand forms (Raft, Raft Computer, Raft
// Desktop, …) stay Latin. Plurals use `one` (which also covers 0) and `other`.

