  "settings.slackBridge.authorizerMissingTitle": 'Os canais privados precisam de uma nova autorização do Slack',
  "settings.slackBridge.authorizerMissingDescription": 'Esta conexão foi autorizada antes de o Raft registrar quem a autorizou, então o Raft não consegue confirmar que essa pessoa vê os canais privados pareados, e esses pares pararam de sincronizar. Tentar a verificação de novo não resolve. Atualize a autorização do Slack com uma conta que participe desses canais.',
  "settings.slackBridge.authorizerMissingReadOnly": 'Esta conexão foi autorizada antes de o Raft registrar quem a autorizou, então o Raft não consegue confirmar que essa pessoa vê os canais privados pareados, e esses pares pararam de sincronizar. Um proprietário ou administrador do servidor precisa atualizar a autorização do Slack com uma conta que participe desses canais.',
  "settings.slackBridge.reauthorize": "Atualizar autorização do Slack",
  "settings.slackBridge.oauthReturn.title": "A autorização do Slack não foi concluída",
  "settings.slackBridge.oauthReturn.cancelled": "A autorização foi cancelada ou recusada no Slack. Nada foi alterado; você pode tentar novamente.",
  "settings.slackBridge.oauthReturn.retryable": "O Slack ficou temporariamente indisponível. Nada foi alterado; tente novamente em alguns minutos.",
  "settings.slackBridge.oauthReturn.unconfirmed": "O Raft não conseguiu confirmar se o Slack concluiu a autorização. Atualize esta página daqui a um minuto e verifique o estado atual antes de tentar novamente.",
  "settings.slackBridge.oauthReturn.identityConflict": "Você autorizou um espaço de trabalho (ou app) do Slack diferente daquele ao qual este servidor do Raft já está conectado. Autorize o mesmo espaço de trabalho ou desconecte-o primeiro.",
  "settings.slackBridge.oauthReturn.failed": "A autorização do Slack não foi concluída e nada foi alterado. Tente novamente; se continuar falhando, entre em contato com o suporte do Raft e informe o código {code}.",
  "settings.slackBridge.disconnectDescription": "A desconexão revoga a credencial do Slack deste servidor do Raft, todos os mapeamentos de canais, as autorizações de envio e os vínculos de identidade. Ela não desinstala o app no Slack; para reconectar, será necessária uma nova autorização.",
