  "settings.slackBridge.mentionCleanupTitle": "Alguns grupos de usuários antigos do Slack ainda precisam ser limpos",
  "settings.slackBridge.mentionCleanupPending": "Os membros atuais já estão disponíveis no menu @ do Slack. Alguns grupos antigos ou duplicados ainda precisam ser limpos. O Raft tentará novamente; se o Slack se recusar a desativá-los, talvez um administrador do Slack precise removê-los. A sincronização de mensagens não é afetada.",
  "settings.slackBridge.mentionSyncTitle": "Alguns membros ainda não podem ser escolhidos no menu @ do Slack",
  "settings.slackBridge.mentionSyncRestricted": "As mensagens são sincronizadas normalmente e, no Slack, digitar o @nome de um membro do Raft continua funcionando quando ninguém mais no canal tem esse nome. Para que esses membros também apareçam no menu @ do Slack, um administrador do Slack precisa permitir que os membros criem grupos de usuários: Configurações do espaço de trabalho → Permissões → Grupos de usuários.",
  "settings.slackBridge.mentionSyncMissingScope": "As mensagens são sincronizadas normalmente e, no Slack, digitar o @nome de um membro do Raft continua funcionando quando ninguém mais no canal tem esse nome. Para que esses membros também apareçam no menu @ do Slack, o Raft precisa de mais uma permissão do Slack: use “Atualizar autorização do Slack” abaixo.",
  "settings.slackBridge.mentionSyncNameTaken": "As mensagens são sincronizadas normalmente e, no Slack, digitar o @nome de um membro do Raft continua funcionando quando ninguém mais no canal tem esse nome. {count, plural, one {# membro não pôde ser incluído} other {# membros não puderam ser incluídos}} no menu @ do Slack porque todos os nomes que o Raft tentou já estão em uso no Slack. Para resolver, altere o nome no Raft ou libere o nome no Slack.",
  "settings.slackBridge.mentionSyncGeneric": "As mensagens são sincronizadas normalmente e, no Slack, digitar o @nome de um membro do Raft continua funcionando quando ninguém mais no canal tem esse nome. O Slack se recusou a listar alguns deles no menu @ ({code}); o Raft continua tentando.",
