  "migration.error.hostedMemoryUnimportable": "Não é possível levar o MEMORY.md do agente para a nuvem: ele é grande demais, não é texto simples ou foi recusado pela nuvem. Peça ao agente para reduzir o MEMORY.md a texto simples e tente novamente.",
  "migration.error.notCancelable": "O agente já foi migrado para a nuvem, então esta migração não pode mais ser cancelada.",
