  "migration.error.proPlanRequired": "A migração de agentes exige o plano Pro. Faça upgrade deste servidor para o Pro antes de tentar novamente.",
  "migration.error.transportNotProvisioned": "O Raft não conseguiu preparar uma transferência segura entre estes computadores. Verifique se os dois estão online e atualizados e tente novamente.",
  "migration.error.transportProvisionFailed": "O Raft não conseguiu preparar a transferência. Verifique se os dois computadores estão online e tente novamente.",
  "migration.error.transportLost": "A conexão entre os dois computadores caiu durante a transferência. Verifique se os dois estão online e tente novamente.",
  "migration.error.transportLostEvent": "A conexão entre os dois computadores caiu durante a transferência.",
  "migration.error.transportLostAt": "A conexão entre os dois computadores caiu em {time}, durante a transferência.",
  "migration.error.transportLostRetryReady": "Os dois computadores estão online agora, então você pode tentar novamente.",
  "migration.error.transportLostRetryOneOffline": "Coloque {computer} online e tente novamente.",
  "migration.error.transportLostRetryBothOffline": "Coloque {source} e {target} online e tente novamente.",
  "migration.error.transportLostRetryUnknown": "Verifique se os dois computadores estão online e tente novamente.",
  "migration.error.entryCountLimitExceeded": "O espaço de trabalho tem arquivos e pastas demais para migrar. Peça ao agente para excluir as pastas de que não precisa mais ou listá-las no .raftmigrateignore e tente novamente.",
  "migration.error.entryCountLimitExceededWithDetails": "O espaço de trabalho tem {count, number} arquivos e pastas; a migração aceita até {limit, number}.{paths, select, none {} other { A maioria está em {paths}.}} Peça ao agente para excluir as pastas de que não precisa mais ou listá-las no .raftmigrateignore e tente novamente.",
  "migration.error.workspaceAlreadyExists": "O computador de destino não conseguiu instalar o agente porque esse espaço de trabalho já existe. Confira qual cópia é a atual, mova ou faça backup do espaço de trabalho em conflito e tente novamente. O Raft não o exclui automaticamente.",
  "migration.error.workspaceCompleteOldCopy": "O computador de destino encontrou uma cópia já concluída deste espaço de trabalho e parou antes de substituí-la. Confirme qual cópia é a atual, mova ou faça backup da cópia antiga e tente novamente. O Raft não a exclui automaticamente.",
  "migration.error.workspaceAlreadyExistsAt": "Já existe um espaço de trabalho em {path} no computador de destino, então o agente não foi instalado. Renomeie ou mova essa pasta — por exemplo, basta acrescentar .bak ao nome — e inicie a migração novamente. Antes de movê-la, confira se não é uma cópia de que você ainda precisa: o Raft nunca a exclui, e, se você movê-la, ela continua naquele computador.",
  "migration.error.workspaceCompleteOldCopyAt": "Uma cópia concluída deste espaço de trabalho, deixada por uma migração anterior, está em {path} no computador de destino, então o Raft parou em vez de substituí-la. Renomeie ou mova essa pasta — por exemplo, basta acrescentar .old ao nome — e inicie a migração novamente. Antes de movê-la, confira qual cópia é a atual: o Raft nunca a exclui, e, se você movê-la, ela continua naquele computador.",
  "migration.error.controlManifestInvalid": "O computador de origem gerou metadados de transferência que o computador de destino não conseguiu verificar. Atualize o Raft Computer nos dois computadores e tente novamente.",
  "migration.error.refInvalid": "A referência da migração está ausente ou é inválida. Atualize o status da migração antes de tentar novamente.",
  "migration.error.revisionInvalid": "O status da migração está incompleto. Atualize-o antes de tentar cancelar novamente.",
  "migration.error.notFound": "Esta migração não está mais disponível. Atualize o status da migração.",
  "migration.error.revisionStale": "A migração mudou antes de esta ação ser concluída. Atualize a página e tente novamente.",
  "migration.error.concurrentUpdate": "A migração foi alterada por outra operação ao mesmo tempo. Atualize a página e tente novamente.",
  "migration.error.cancelFailed": "O Raft não conseguiu solicitar o cancelamento. Atualize o status da migração e tente novamente.",
  "migration.error.startFailed": "Não foi possível iniciar a migração. Verifique os dois computadores e tente novamente.",
  "migration.error.statusFailed": "Não foi possível carregar o status da migração. Atualize a página e tente novamente.",
  "migration.error.objectStoreUnreachable": "Um dos computadores não conseguiu acessar o armazenamento de migração do Raft por 5 minutos. Verifique a rede, o proxy ou o firewall dele e tente novamente.",
  "migration.error.computerOwnerDeleted": "A migração parou porque o dono de um dos computadores excluiu a conta do Raft. Mova o agente para outro computador.",
  "migration.error.targetComputerDetached": "Esta migração foi interrompida porque o computador de destino foi desvinculado antes que o agente pudesse ser movido para ele. O agente continua onde estava; escolha outro computador.",
  "migration.error.transferSummaryInvalid": "O computador de origem não conseguiu contar os arquivos excluídos desta migração. Atualize o Raft Computer no computador de origem para a versão mais recente e tente novamente.",
  "migration.error.userIgnoreWriteFailed": "Não foi possível salvar no computador de origem os caminhos que você escolheu deixar de fora, então a migração parou. Nada foi movido.",
  "migration.error.failedGeneric": "Algo deu errado durante a transferência. Tente novamente.",
