  "migration.error.bundleTooLarge": "O espaço de trabalho é grande demais para migrar.{items, select, none {} other { Maiores itens (antes da compactação): {items}.}} Peça ao agente para excluir os arquivos grandes de que não precisa mais ou listá-los no .raftmigrateignore e tente novamente.",
